// The app's own i18n runtime (no browser i18n API: it has no Sorani `ckb`).
// Catalogs are generated by l10n/generate.py from l10n/strings.json — never edit them.
import ar from './ar.json'
import ckb from './ckb.json'
import en from './en.json'

export type Language = 'en' | 'ckb' | 'ar'

/** In the order the phones list them (iOS `AppLanguage.allCases`). */
export const LANGUAGES: readonly Language[] = ['en', 'ckb', 'ar']

/** Each language's name in its own script, as on iOS (`AppLanguage.displayName`). */
export const LANGUAGE_NAMES: Record<Language, string> = {
  en: 'English',
  ckb: 'کوردی',
  ar: 'العربية',
}

type Catalog = Record<string, string>
const CATALOGS: Record<Language, Catalog> = { en, ar, ckb }

export function isRtl(language: Language): boolean {
  return language !== 'en'
}

/**
 * Looks up `key` in `language`, falling back to English, then to the key itself.
 * `{0}`, `{1}` … are replaced by `args` in order.
 */
export function translate(language: Language, key: string, ...args: Array<string | number>): string {
  const text = CATALOGS[language][key] ?? CATALOGS.en[key] ?? key
  return text.replace(/\{(\d+)\}/g, (match, index: string) => {
    const value = args[Number(index)]
    return value === undefined ? match : String(value)
  })
}
